#include <iostream>
#include <algorithm>

using namespace std;

int fibonacci(int n) {
    // Base cases
    if (n == 0) {
        return 0;
    } else if (n == 1) {
        return 1;
    } else {
        return fibonacci(int (n-1)) + fibonacci(int (n-2));
    }
}

int main() {
    int n;
    cout << "Enter the number: ";
    cin >> n;
    try {
    cout << "The " << n << "th Fibonacci number is: " << fibonacci(n));
    } else {
        cout << "The number " << n << " is out of range of Fibonacci series.";
    }
    cin.get();
    return 0;
}

